INSERT INTO "molecular_clouds_dark_nebulae" ("object_id", "cloud_name", "cloud_type", "constellation", "distance_ly", "mass_solar", "dimensions_pc", "core_temp_k", "extinction_av_mag", "primary_tracers", "collapse_star_formation_status") VALUES
  ('GMC_TAURUS', 'Taurus Molecular Cloud', 'Giant Molecular Cloud', 'TAU', 430.0, 24000.0, '30 x 10 pc', 10.0, 8.0, '12CO, 13CO, C18O, NH3, HC3N', 'TMC-1, L1495 filament, ~400 Class 0-III YSOs; prototypical low-mass star formation'),
  ('GMC_ORION_A', 'Orion A Cloud (OMC-1)', 'Giant Molecular Cloud', 'ORI', 1344.0, 100000.0, '40 x 10 pc', 25.0, 15.0, '12CO, CS(2-1), HCO+, HCN, 850um', 'Trapezium cluster, BN-KL, ~3,000 YSOs; high-mass star forming engine'),
  ('GMC_ORION_B', 'Orion B Cloud (LDN 1630)', 'Giant Molecular Cloud', 'ORI', 1370.0, 80000.0, '35 x 12 pc', 18.0, 12.0, '12CO, 13CO, N2H+, NH3', 'Flame Nebula, Horsehead (B33), M78; massive starburst filaments'),
  ('GMC_PERSEUS', 'Perseus Molecular Cloud', 'Giant Molecular Cloud', 'PER', 980.0, 18000.0, '30 x 10 pc', 12.0, 6.0, '12CO, N2H+, NH3, H13CO+', 'NGC 1333 outflow hub, IC 348 cluster, ~600 YSOs'),
  ('GMC_RHO_OPH', 'Rho Ophiuchi Cloud Complex', 'Giant Molecular Cloud', 'OPH', 456.0, 3000.0, '15 x 8 pc', 15.0, 20.0, '12CO, 13CO, C18O, DCO+', 'L1688 central core, VLA 1623 (Class 0 prototype); high star formation efficiency (14%)'),
  ('GMC_CARINA', 'Carina Nebula Complex (NGC 3372)', 'Giant Molecular Cloud', 'CAR', 7500.0, 700000.0, '80 x 50 pc', 35.0, 25.0, '12CO(2-1), [C II] 158um, CS, H-alpha', 'Trumpler 14/15/16, Eta Carinae LBV; extreme UV feedback and triggered star formation'),
  ('BOK_B68', 'Barnard 68', 'Bok Globule / Pre-stellar Core', 'OPH', 410.0, 2.1, '0.15 x 0.12 pc', 10.5, 35.0, 'C18O, N2H+, NH3, C34S', 'Textbook Bonnor-Ebert sphere in marginal gravitational collapse'),
  ('BOK_B33', 'Horsehead Nebula (Barnard 33)', 'Dark Absorption Pillar', 'ORI', 1370.0, 27.0, '1.5 x 1.0 pc', 18.0, 25.0, 'CO, HCO+, C2H, C4H, PAHs', 'Photo-evaporating pillar sculpted by Sigma Orionis O-star wind'),
  ('BOK_COALSACK', 'Coalsack Nebula (Caldwell 99)', 'Dark Nebula Complex', 'CRU', 590.0, 3500.0, '20 x 15 pc', 14.0, 15.0, '12CO, 13CO, OH 18cm, CH', 'Prominent southern dark cloud; early fragmentation without high-mass stars'),
  ('BOK_PIPE', 'Pipe Nebula (Barnard 59/72)', 'Dark Molecular Nebula', 'OPH', 475.0, 10000.0, '18 x 9 pc', 11.5, 30.0, 'C18O, N2H+, NH3, 850um', 'Magnetically supported stable filamentary cloud with active collapse in B59')
